INSERT INTO learning_topics (id, title, category, description, objective, content, content_type, estimated_minutes, required, deadline, difficulty, tags, references_data, created_by, created_at, updated_at, video_url, pdf_url, assigned_unit_ids, assigned_user_ids) VALUES ('t1', 'Giáo dục chính trị: Kiên định mục tiêu lý tưởng cách mạng', 'Giáo dục chính trị', 'Nội dung bồi dưỡng lập trường tư tưởng vững vàng, kiên định mục tiêu độc lập dân tộc gắn liền với chủ nghĩa xã hội của Đảng Cộng sản Việt Nam.', 'Giúp chiến sĩ dân quân hiểu rõ bản chất cách mạng, giữ vững tư tưởng trước những thông tin xuyên tạc, trung thành với Tổ quốc và nhân dân.', '### 1. Ý NGHĨA QUAN TRỌNG CỦA LÝ TƯỞNG CÁCH MẠNG
INSERT INTO learning_topics (id, title, category, description, objective, content, content_type, estimated_minutes, required, deadline, difficulty, tags, references_data, created_by, created_at, updated_at, video_url, pdf_url, assigned_unit_ids, assigned_user_ids) VALUES ('t2', 'Phổ biến giáo dục pháp luật: Nghĩa vụ quân sự và trách nhiệm công dân', 'Phổ biến giáo dục pháp luật', 'Giới thiệu các nội dung cốt lõi của Luật Nghĩa vụ quân sự 2015, quyền lợi và nghĩa vụ của công dân khi tham gia bảo vệ Tổ quốc.', 'Nắm vững tiêu chuẩn tuyển quân, độ tuổi gọi nhập ngũ, các trường hợp được hoãn hoặc miễn gọi nhập ngũ, trách nhiệm của bản thân và gia đình.', '### 1. Ý NGHĨA CỦA LUẬT NGHĨA VỤ QUÂN SỰ
INSERT INTO learning_topics (id, title, category, description, objective, content, content_type, estimated_minutes, required, deadline, difficulty, tags, references_data, created_by, created_at, updated_at, video_url, pdf_url, assigned_unit_ids, assigned_user_ids) VALUES ('t3', 'Kỷ luật Quân đội và nền nếp chính quy', 'Kỷ luật Quân đội', 'Quán triệt 12 điều kỷ luật khi quan hệ với nhân dân và chế độ sinh hoạt, học tập, công tác trong ngày, trong tuần của chiến sĩ.', 'Góp phần nâng cao ý thức chấp hành pháp luật nhà nước, kỷ luật quân đội, xây dựng đơn vị vững mạnh toàn diện mẫu mực, tiêu biểu.', '### 1. 12 ĐIỀU KỶ LUẬT KHI QUAN HỆ VỚI NHÂN DÂN
INSERT INTO learning_topics (id, title, category, description, objective, content, content_type, estimated_minutes, required, deadline, difficulty, tags, references_data, created_by, created_at, updated_at, video_url, pdf_url, assigned_unit_ids, assigned_user_ids) VALUES ('t4', 'Công tác dân vận trong tình hình mới', 'Công tác Đảng, công tác chính trị', 'Vai trò, nhiệm vụ công tác dân vận của lực lượng vũ trang nhân dân địa phương nhằm củng cố khối đại đoàn kết toàn dân và thế trận lòng dân vững chắc.', 'Hiểu rõ phương châm ''Dân biết, dân bàn, dân làm, dân kiểm tra, dân giám sát, dân thụ hưởng'' và cách áp dụng vào thực tiễn địa phương.', '### 1. KHÁI NIỆM VÀ PHƯƠNG CHÂM DÂN VẬN
INSERT INTO learning_topics (id, title, category, description, objective, content, content_type, estimated_minutes, required, deadline, difficulty, tags, references_data, created_by, created_at, updated_at, video_url, pdf_url, assigned_unit_ids, assigned_user_ids) VALUES ('t5', 'Phòng chống thông tin xấu độc trên không gian mạng', 'Thời sự chính trị', 'Nhận diện các âm mưu thủ đoạn phá hoại tư tưởng trên không gian mạng, trang bị kỹ năng chọn lọc thông tin lành mạnh cho chiến sĩ.', 'Tăng cường sức đề kháng trước luận điệu xuyên tạc, bôi nhọ của các thế lực phản động, xây dựng văn hóa ứng xử lành mạnh trên mạng xã hội.', '### 1. THỦ ĐOẠN PHÁ HOẠI TƯ TƯỞNG
INSERT INTO learning_topics (id, title, category, description, objective, content, content_type, estimated_minutes, required, deadline, difficulty, tags, references_data, created_by, created_at, updated_at, video_url, pdf_url, assigned_unit_ids, assigned_user_ids) VALUES ('t6', 'Truyền thống lực lượng vũ trang địa phương', 'Giáo dục chính trị', 'Tìm hiểu lịch sử anh dũng, các chiến công tiêu biểu của lực lượng vũ trang nhân dân tỉnh, huyện và xã Yên Thế qua các thời kỳ.', 'Khơi dậy niềm tự hào dân tộc, truyền thống quê hương cách mạng, củng cố ý chí quyết tâm phấn đấu học tập, rèn luyện của cán bộ chiến sĩ.', '### LỊCH SỬ HÌNH THÀNH VÀ CHIẾN CÔNG TIÊU BIỂU
INSERT INTO learning_topics (id, title, category, description, objective, content, content_type, estimated_minutes, required, deadline, difficulty, tags, references_data, created_by, created_at, updated_at, video_url, pdf_url, assigned_unit_ids, assigned_user_ids) VALUES ('t7', 'Luật Dân quân tự vệ năm 2019', 'Phổ biến giáo dục pháp luật', 'Phổ biến các quy định cốt lõi của Luật Dân quân tự vệ 2019 về vị trí, chức năng, nhiệm vụ, độ tuổi và thời hạn tham gia dân quân tự vệ.', 'Nắm vững nghĩa vụ tham gia dân quân tự vệ, chế độ chính sách được hưởng và trách nhiệm bảo vệ địa bàn.', '### 1. VỊ TRÍ, CHỨC NĂNG CỦA LỰC LƯỢNG DÂN QUÂN TỰ VỆ
INSERT INTO learning_topics (id, title, category, description, objective, content, content_type, estimated_minutes, required, deadline, difficulty, tags, references_data, created_by, created_at, updated_at, video_url, pdf_url, assigned_unit_ids, assigned_user_ids) VALUES ('t8', 'Chế độ chính trị nước Cộng hòa xã hội chủ nghĩa Việt Nam', 'Giáo dục chính trị', 'Tìm hiểu vị trí lãnh đạo của Đảng, vai trò quản lý của Nhà nước và quyền làm chủ của nhân dân theo Hiến pháp 2013.', 'Xây dựng nhận thức đúng đắn về hệ thống chính trị Việt Nam, củng cố niềm tin vào sự lãnh đạo của Đảng.', '### 1. BẢN CHẤT CỦA NHÀ NƯỚC TA
INSERT INTO learning_topics (id, title, category, description, objective, content, content_type, estimated_minutes, required, deadline, difficulty, tags, references_data, created_by, created_at, updated_at, video_url, pdf_url, assigned_unit_ids, assigned_user_ids) VALUES ('t9', 'Xây dựng nền quốc phòng toàn dân vững mạnh', 'Giáo dục chính trị', 'Quan điểm chỉ đạo của Đảng về xây dựng nền quốc phòng toàn dân gắn với thế trận an ninh nhân dân vững mạnh toàn diện.', 'Giúp chiến sĩ hiểu rõ trách nhiệm của địa phương trong xây dựng khu vực phòng thủ, thế trận quốc phòng toàn dân.', '### 1. KHÁI NIỆM QUỐC PHÒNG TOÀN DÂN
INSERT INTO learning_topics (id, title, category, description, objective, content, content_type, estimated_minutes, required, deadline, difficulty, tags, references_data, created_by, created_at, updated_at, video_url, pdf_url, assigned_unit_ids, assigned_user_ids) VALUES ('t10', 'Thông tư 143/2020/TT-BQP về xử lý kỷ luật quân đội', 'Quy định điều lệnh', 'Phổ biến chi tiết các hình thức kỷ luật đối với quân nhân vi phạm nề nếp kỷ luật, tác phong quân đội.', 'Răn đe, giáo dục chiến sĩ giữ gìn tác phong chuẩn mực, không vi phạm pháp luật và quy chế đơn vị.', '### 1. PHẠM VI ÁP DỤNG
INSERT INTO learning_sections (id, topic_id, title, content, section_order, required) VALUES ('sec_t1_1', 't1', 'Phần 1: Khái niệm, vai trò và ý nghĩa cốt lõi', 'Nội dung phần 1 tập trung giới thiệu bối cảnh lịch sử, ý nghĩa quan trọng và vai trò thực tiễn của bài học "Giáo dục chính trị: Kiên định mục tiêu lý tưởng cách mạng" đối với sự nghiệp xây dựng bảo vệ Tổ quốc.', 1, true);
INSERT INTO learning_sections (id, topic_id, title, content, section_order, required) VALUES ('sec_t1_2', 't1', 'Phần 2: Các nội dung trọng tâm và văn bản quy phạm liên quan', 'Phân tích sâu các văn bản quy định của Đảng, Nhà nước, Bộ Quốc phòng, hoặc các lý thuyết lý luận của chuyên đề "Giáo dục chính trị: Kiên định mục tiêu lý tưởng cách mạng".', 2, true);
INSERT INTO learning_sections (id, topic_id, title, content, section_order, required) VALUES ('sec_t1_3', 't1', 'Phần 3: Trách nhiệm và hành động thực tiễn tại đơn vị cơ sở', 'Xác định rõ vai trò trách nhiệm của bản thân cán bộ, chiến sĩ tại Ban CHQS xã Yên Thế và các tổ dân quân địa phương trong việc học tập, chấp hành lý luận bài học "Giáo dục chính trị: Kiên định mục tiêu lý tưởng cách mạng".', 3, false);
