INSERT INTO learning_sections (id, topic_id, title, content, section_order, required) VALUES ('sec_t5_3', 't5', 'Phần 3: Trách nhiệm và hành động thực tiễn tại đơn vị cơ sở', 'Xác định rõ vai trò trách nhiệm của bản thân cán bộ, chiến sĩ tại Ban CHQS xã Yên Thế và các tổ dân quân địa phương trong việc học tập, chấp hành lý luận bài học "Phòng chống thông tin xấu độc trên không gian mạng".', 3, false);
