INSERT INTO questions (id, topic_id, type, question_text, options, correct_answers, explanation, difficulty, reference_info, tags) VALUES ('q1_1', 't1', 'single', 'Nền tảng tư tưởng, kim chỉ nam hành động của Đảng Cộng sản Việt Nam và Cách mạng Việt Nam là gì?', '["Chủ nghĩa thực dụng và lý thuyết khoa học hiện đại.","Chủ nghĩa Mác - Lênin và Tư tưởng Hồ Chí Minh.","Truyền thống yêu nước và bản sắc văn hóa dân tộc đơn thuần.","Kinh nghiệm cách mạng của các nước phương Tây."]'::jsonb, '[1]'::jsonb, 'Chủ nghĩa Mác - Lênin và Tư tưởng Hồ Chí Minh là nền tảng tư tưởng, kim chỉ nam hành động đã được khẳng định rõ trong Cương lĩnh của Đảng.', 'Dễ', 'Hiến pháp 2013', '["Chính trị","Lập trường tư tưởng"]'::jsonb);
INSERT INTO questions (id, topic_id, type, question_text, options, correct_answers, explanation, difficulty, reference_info, tags) VALUES ('q1_2', 't1', 'true_false', 'Lực lượng dân quân tự vệ là lực lượng vũ trang quần chúng thoát ly khỏi mọi hoạt động sản xuất, công tác của địa phương để tập trung huấn luyện chiến đấu toàn thời gian trong thời bình.', '["Đúng","Sai"]'::jsonb, '[1]'::jsonb, 'Dân quân tự vệ là lực lượng vũ trang quần chúng không thoát ly sản xuất, công tác.', 'Dễ', 'Điều 2 Luật Dân quân tự vệ 2019', '["Dân quân tự vệ","Điều lệnh"]'::jsonb);
INSERT INTO questions (id, topic_id, type, question_text, options, correct_answers, explanation, difficulty, reference_info, tags) VALUES ('q1_3', 't1', 'multiple', 'Nội dung cốt lõi của lý tưởng cách mạng Việt Nam bao gồm những yếu tố nào dưới đây? (Chọn tất cả đáp án đúng)', '["Kiên định mục tiêu độc lập dân tộc và chủ nghĩa xã hội.","Tăng cường chạy đua vũ trang với các quốc gia láng giềng.","Trung thành vô hạn với Tổ quốc và Nhân dân.","Đặt lợi ích cá nhân lên trên lợi ích quốc gia dân tộc."]'::jsonb, '[0,2]'::jsonb, 'Lý tưởng cách mạng luôn kiên định mục tiêu độc lập dân tộc và chủ nghĩa xã hội.', 'Trung bình', 'Tài liệu học tập chính trị', '["Chính trị","Lý tưởng"]'::jsonb);
INSERT INTO questions (id, topic_id, type, question_text, options, correct_answers, explanation, difficulty, reference_info, tags) VALUES ('q1_4', 't1', 'single', 'Để giữ vững lập trường tư tưởng trước thông tin xuyên tạc, chiến sĩ dân quân cần tránh hành vi nào?', '["Học tập chính trị nghiêm túc.","Tin tưởng sự lãnh đạo của Đảng.","Chia sẻ các thông tin giật gân, chưa kiểm chứng trên mạng xã hội.","Đọc báo Quân đội nhân dân chính thống."]'::jsonb, '[2]'::jsonb, 'Tuyệt đối không chia sẻ tin tức chưa kiểm chứng.', 'Trung bình', 'Quy chế đơn vị', '["An ninh mạng"]'::jsonb);
INSERT INTO questions (id, topic_id, type, question_text, options, correct_answers, explanation, difficulty, reference_info, tags) VALUES ('q1_5', 't1', 'single', 'Nghị quyết Đại hội XIII của Đảng xác định mục tiêu phát triển đất nước đến năm 2045 là gì?', '["Trở thành nước đang phát triển, có công nghiệp theo hướng hiện đại.","Trở thành nước phát triển, thu nhập cao, theo định hướng xã hội chủ nghĩa.","Trở thành nền kinh tế lớn nhất thế giới.","Hoàn thành công nghiệp hóa hiện đại hóa sơ bộ."]'::jsonb, '[1]'::jsonb, 'Nghị quyết xác định tầm nhìn đến năm 2045 trở thành nước phát triển, thu nhập cao theo định hướng XHCN.', 'Khó', 'Nghị quyết Đại hội XIII', '["Đại hội XIII","Nghị quyết"]'::jsonb);
INSERT INTO questions (id, topic_id, type, question_text, options, correct_answers, explanation, difficulty, reference_info, tags) VALUES ('q2_1', 't2', 'single', 'Theo Luật Nghĩa vụ quân sự 2015, độ tuổi gọi nhập ngũ bình thường của công dân nam trong thời bình là bao nhiêu?', '["Từ đủ 18 tuổi đến hết 22 tuổi.","Từ đủ 18 tuổi đến hết 25 tuổi.","Từ đủ 17 tuổi đến hết 25 tuổi.","Từ đủ 18 tuổi đến hết 30 tuổi."]'::jsonb, '[1]'::jsonb, 'Độ tuổi gọi nhập ngũ từ đủ 18 tuổi đến hết 25 tuổi; nếu học đại học/cao đẳng được tạm hoãn thì đến hết 27 tuổi.', 'Dễ', 'Luật Nghĩa vụ quân sự 2015', '["NVQS","Độ tuổi"]'::jsonb);
INSERT INTO questions (id, topic_id, type, question_text, options, correct_answers, explanation, difficulty, reference_info, tags) VALUES ('q2_2', 't2', 'single', 'Thời hạn phục vụ tại ngũ trong thời bình của hạ sĩ quan, binh sĩ Quân đội nhân dân Việt Nam là bao nhiêu tháng?', '["12 tháng.","18 tháng.","24 tháng.","36 tháng."]'::jsonb, '[2]'::jsonb, 'Thời hạn phục vụ tại ngũ trong thời bình là 24 tháng.', 'Dễ', 'Điều 21 Luật Nghĩa vụ quân sự 2015', '["NVQS"]'::jsonb);
INSERT INTO questions (id, topic_id, type, question_text, options, correct_answers, explanation, difficulty, reference_info, tags) VALUES ('q2_3', 't2', 'scenario', 'Anh Nam đang là sinh viên học hệ chính quy tại một trường Đại học. Anh nhận được Lệnh gọi khám sức khỏe nghĩa vụ quân sự. Theo pháp luật hiện hành, anh Nam xử lý như thế nào là đúng nhất?', '["Tự ý xé lệnh gọi vì cho rằng mình là sinh viên đương nhiên được miễn.","Cần chấp hành đi khám sức khỏe theo lệnh gọi, đồng thời nộp Giấy xác nhận học tập cho Ban CHQS xã để làm thủ tục xin tạm hoãn gọi nhập ngũ.","Nhờ người khác đi khám thay mình.","Trốn tránh không đến điểm khám và không nộp giấy tờ gì."]'::jsonb, '[1]'::jsonb, 'Công dân phải chấp hành lệnh gọi khám tuyển, việc tạm hoãn sẽ được xem xét dựa trên hồ sơ hợp lệ.', 'Trung bình', 'Luật NVQS 2015', '["Tình huống","NVQS"]'::jsonb);
INSERT INTO questions (id, topic_id, type, question_text, options, correct_answers, explanation, difficulty, reference_info, tags) VALUES ('q2_4', 't2', 'true_false', 'Hành vi trốn tránh lệnh gọi nhập ngũ sau khi đã bị phạt hành chính vẫn chỉ bị phạt tiền tiếp tục mà không bao giờ bị truy cứu trách nhiệm hình sự.', '["Đúng","Sai"]'::jsonb, '[1]'::jsonb, 'Hành vi trốn tránh sau khi đã bị phạt hành chính có thể bị truy cứu trách nhiệm hình sự theo Điều 332 Bộ luật Hình sự.', 'Trung bình', 'Bộ luật Hình sự', '["Pháp luật","Xử phạt"]'::jsonb);
INSERT INTO questions (id, topic_id, type, question_text, options, correct_answers, explanation, difficulty, reference_info, tags) VALUES ('q2_5', 't2', 'multiple', 'Những đối tượng nào sau đây được miễn gọi nhập ngũ trong thời bình? (Chọn tất cả đáp án đúng)', '["Con của liệt sĩ, con của thương binh hạng một.","Tất cả công dân nam là lao động tự do tại địa phương.","Một anh hoặc một em ruột của liệt sĩ.","Công dân nam đang học đại học chính quy."]'::jsonb, '[0,3]'::jsonb, NULL, NULL, NULL, '[]'::jsonb);
