INSERT INTO exams (id, title, description, topic_ids, duration_minutes, question_count, start_date, end_date, passing_score, allow_review, status, lifecycle_status, created_by) VALUES ('e1', 'Kiểm tra trắc nghiệm Giáo dục chính trị & Pháp luật đợt 1 năm 2026', 'Kỳ thi đánh giá định kỳ bắt buộc đối với toàn bộ lực lượng dân quân tự vệ thuộc Ban CHQS xã Yên Thế nhằm kiểm tra nhận thức lý luận chính trị.', '["t1","t2"]'::jsonb, 15, 4, '2026-06-20T00:00:00Z', '2026-07-05T23:59:59Z', 5, true, 'active', 'published', '00000000-0000-4000-8000-000000000003');
