INSERT INTO news (id, title, category, summary, content, image_url, visibility, status, author_id, published_at) VALUES ('n1', 'Ban CHQS xã Yên Thế tổ chức ra quân huấn luyện dân quân năm 2026', 'Tin tức huấn luyện', 'Sáng ngày 15/6, Ban Chỉ huy Quân sự xã Yên Thế tổ chức lễ ra quân huấn luyện và phát động phong trào thi đua cho lực lượng dân quân cơ động và dân quân tại chỗ.', 'Sáng ngày 15/6, trong không khí thi đua sôi nổi của địa phương, Ban CHQS xã Yên Thế đã tổ chức thành công Lễ ra quân huấn luyện dân quân năm 2026. Tham dự buổi lễ có đồng chí Bí thư Đảng ủy xã, Chủ tịch UBND xã cùng đại diện cơ quan quân sự cấp trên.
INSERT INTO news (id, title, category, summary, content, image_url, visibility, status, author_id, published_at) VALUES ('n2', 'Tuyên dương gương dân quân dũng cảm cứu hộ tài sản nhân dân trong bão lũ', 'Gương sáng chiến sĩ', 'Chiến sĩ dân quân tại chỗ thôn Tân Sỏi - đồng chí Hoàng Văn Nam vừa được Đảng ủy, UBND xã tuyên dương khen thưởng đột xuất vì hành động dũng cảm cứu tài sản nhân dân.', 'Trong đợt mưa lũ lịch sử ảnh hưởng bởi hoàn lưu bão vừa qua, nước sông dâng cao đột ngột gây ngập úng nghiêm trọng nhiều hộ dân tại thôn Tân Sỏi. Nhận được tin báo cứu hộ khẩn cấp, đồng chí Hoàng Văn Nam thuộc tổ dân quân tại chỗ thôn Tân Sỏi đã không quản ngại nguy hiểm, bơi qua dòng nước xiết để hỗ trợ vận chuyển an toàn tài sản và 3 người già, trẻ nhỏ đến nơi tránh trú an toàn.
INSERT INTO news (id, title, category, summary, content, image_url, visibility, status, author_id, published_at) VALUES ('n3', 'Thông báo lịch sinh hoạt chính trị và học tập Nghị quyết tháng 6 năm 2026', 'Thông báo đơn vị', 'Ban CHQS xã Yên Thế thông báo lịch học tập chính trị tập trung về xây dựng lập trường tư tưởng cách mạng vững vàng cho toàn thể cán bộ chiến sĩ.', 'Để thực hiện nghiêm túc kế hoạch giáo dục chính trị năm 2026, Đảng ủy quân sự xã thông báo lịch học tập chuyên đề tập trung:
INSERT INTO news (id, title, category, summary, content, image_url, visibility, status, author_id, published_at) VALUES ('n4', 'Tin tức giáo dục quân sự địa phương số 4: Đạt kết quả cao trong huấn luyện', 'Bản tin tuyên truyền', 'Tóm tắt bản tin thời sự quốc phòng an ninh địa bàn Yên Thế số 4, đánh giá công tác giáo dục chính trị pháp luật đạt chất lượng cao.', 'Chi tiết bản tin thời sự: Lực lượng vũ trang xã Yên Thế luôn nỗ lực đạt kết quả tốt nhất trong các bài học chính trị lý luận và kỹ thuật chiến thuật quân sự năm 2026.
